        pub fn callGetMatchResult(self: *Client, user_ctx: *anyopaque, build: ?GetMatchResult.BuildFn, on_return: GetMatchResult.Callback) !u32 {
            const ctx = try self.peer.allocator.create(GetMatchResult.CallContext);
